import json

# Try: Make shapes convex by filling in any gaps within their hull
def get_hull_rect(grid, color):
    """Get minimum rectangle containing all pixels of given color"""
    rows = [r for r in range(len(grid)) for c in range(len(grid[r]) 
                                   if grid[r][c] == color]
    cols = [c for r in range(len(grid)) for c in range(len(grid[r])) 
            if grid[r][c] == color]
    if not rows or not cols:
        return None
    return (min(rows), max(rows), min(cols), max(cols))

output_grid = [[0]*12 for _ in range(11)]

# Get bbox for each color
bbox_4 = get_hull_rect(input_grid, 4)
bbox_6 = get_hull_rect(input_grid, 6)
print(f"Bbox 4: {bbox_4}")
print(f"Bbox 6: {bbox_6}")

# What if I fill only the "interior" points, not the edges?
# For shape 4: interior would exclude the border of the bbox

def fill_interior_bbox(grid, color, r_min, r_max, c_min, c_max):
    """Fill only the interior (not border) of the bbox"""
    new_grid = [[x for x in row] for row in grid]
    # Interior excludes outermost rows and columns
    for r in range(r_min+1, r_max):
        for c in range(c_min+1, c_max):
            if new_grid[r][c] != color:
                new_grid[r][c] = color
    return new_grid

output = [[0]*12 for _ in range(11)]
for r in range(11):
    for c in range(12):
        output[r][c] = input_grid[r][c]

if bbox_4:
    output = fill_interior_bbox(output, 4, *bbox_4)
if bbox_6:
    output = fill_interior_bbox(output, 6, *bbox_6)

print("Interior-only filled:")
for r in range(11):
    print(' '.join(str(x) for x in output[r]))

print("\nJSON:", json.dumps(output))

